@implements IDisposable
@inject IAddressValidator AddressValidator

<h3>Shipping Information</h3>

<div class="form-group">
    <label for="name">Name</label>
    <input id="name" @bind="Shipping.Name" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label for="address">Address</label>
    <input id="address" @bind="Shipping.Address" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label for="city">City</label>
    <input id="city" @bind="Shipping.City" disabled="@_isValidating" />
</div>

<div class="form-group">
    <label for="zip">Zip Code</label>
    <input id="zip" @bind="Shipping.ZipCode" disabled="@_isValidating" />
</div>

@if (!string.IsNullOrEmpty(_validationError))
{
    <div class="validation-error">@_validationError</div>
}

<button @onclick="HandleNext" disabled="@_isValidating">
    @if (_isValidating)
    {
        <span class="spinner"></span>
        <span>Validating…</span>
    }
    else
    {
        <span>Next</span>
    }
</button>

@code {
    [Parameter]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _validationError;

    private async Task HandleNext()
    {
        _validationError = null;

        // Cancel any in-flight validation before starting a new one.
        CancelPendingValidation();

        var cts = new CancellationTokenSource();
        _cts = cts;
        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, cts.Token);

            cts.Token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check your entry.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — either the user re-clicked Next or
            // the component was disposed. Nothing to do.
        }
        finally
        {
            // Only clear the flag if this is still the active operation.
            if (_cts == cts)
            {
                _isValidating = false;
            }

            cts.Dispose();
        }
    }

    private void CancelPendingValidation()
    {
        try
        {
            _cts?.Cancel();
        }
        catch (ObjectDisposedException)
        {
            // Already cleaned up — safe to ignore.
        }
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

